    def __init__(self) -> None:
        self._plots: list[PlotSpec] = []
        self._proc: multiprocessing.process.BaseProcess | None = None
        self._parent_pipe: multiprocessing.connection.Connection | None = None
        self._cols: list[str] = []

    def reset_plots(self) -> None:
        self._plots = []

    def plot(self, x: Any, y: Any, z: Any) -> None:
        def to_names(v: Any) -> list[str]:
            if v is None:
                return []

            def n(p: Any) -> str:
                if isinstance(p, str):
                    return p
                return p.full_name

            if isinstance(v, list):
                nl: list[str] = []
                for item in v:
                    nl.append(n(item))
                return nl
            return [n(v)]

        xs, ys, zs = to_names(x), to_names(y), to_names(z)
        if len(xs) > 1 and len(ys) > 1 and len(xs) != len(ys):
            raise ValueError("if multiple xs given, number must be same as ys")
        if len(zs) == 1 and (len(xs) > 1 or len(ys) > 1):
            raise ValueError("2d plots can only have one x and y")
        if len(zs) > 1:
            raise ValueError("can only have one z parameter")
        self._plots.append((xs, ys, zs))

    def set_cols(self, cols: list[str]) -> None:
        self._cols = cols

    def _format_data_map(self, data: list[float]) -> DataMap:
        m: DataMap = {}
        for k, v in zip(self._cols, data):
            m[k] = v
        return m

